window.bookSummaryJSON = "<p>This collection of fantasy short stories are from the three winners of Remastered Words 2016 audio anthology, including a tale from one of our judges, Adrian Tchaikovsky with \"The Groppler's Harvest\", which was first published in the British Fantasy Society's 2013 anthology. Listen as our bards regale you with treacherous journeys and fables worthy of the smallest campfire to the most renowned taverns, where sometimes only the ultimate price is enough. So charge your tankards, goblets, and mugs, sit back and enjoy a fabled journey or two. </p>"; 
